args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthYear WHERE {
  VALUES ?film { dbr:Four_for_Venice dbr:Gypped_in_the_Penthouse }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bdate . }
  OPTIONAL { ?director rdfs:comment ?comment . }
  OPTIONAL { ?director dbo:abstract ?abstract . }
  BIND(
    COALESCE(
      xsd:integer(SUBSTR(STR(?bdate),1,4)),
      xsd:integer(REPLACE(?comment, ".*(\\d{4}).*", "$1")),
      xsd:integer(REPLACE(?abstract, ".*(\\d{4}).*", "$1"))
    ) AS ?birthYear
  )
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
}
ORDER BY DESC(?birthYear)
LIMIT 1

